```php
<?php
declare(strict_types=1);
class Ticket {
    public const PREFIX = 'T';
    private static int $next = 1;
    public static function create(): string {
        return self::PREFIX . self::$next++;
    }
}
echo Ticket::create(), ' ', Ticket::create(), "\n";
```

